create table if not exists app_schema_migrations(migration_number text primary key,migration_name text not null,checksum text not null,applied_at timestamptz not null default now(),applied_by text not null,environment text not null,notes text);
create table if not exists application_operational_errors(id uuid primary key default gen_random_uuid(),occurred_at timestamptz not null default now(),environment text not null,severity text not null check(severity in('warning','error','critical')),feature text not null,operation text not null,safe_code text not null,correlation_id text not null,recoverable boolean not null,safe_message text not null,resolved_at timestamptz,resolution_note text,check(length(safe_message)<=500),check(length(correlation_id)<=80));
create table if not exists application_delivery_attempts(id uuid primary key default gen_random_uuid(),record_type text not null check(record_type in('proposal','change_order','test')),record_id uuid,revision_id uuid,attempt_number integer not null default 1,recipient_domain text,provider text not null default 'resend',status text not null check(status in('pending','sent','failed')),provider_message_id text,correlation_id text not null,last_error_safe_code text,sent_at timestamptz,created_at timestamptz not null default now(),unique(record_type,record_id,revision_id,attempt_number));
create table if not exists application_document_generation(id uuid primary key default gen_random_uuid(),record_type text not null check(record_type in('proposal','signed_proposal','change_order','signed_change_order','synthetic')),record_id uuid,revision_id uuid,document_path text,status text not null check(status in('pending','generating','ready','failed')),generation_version text not null,document_hash text,safe_error_code text,correlation_id text not null,attempt_number integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(record_type,record_id,revision_id,attempt_number));
create index if not exists operational_errors_recent_idx on application_operational_errors(occurred_at desc)where resolved_at is null;create index if not exists delivery_attempts_record_idx on application_delivery_attempts(record_type,record_id,created_at desc);create index if not exists document_generation_record_idx on application_document_generation(record_type,record_id,created_at desc);
create or replace function app_readiness_snapshot()returns jsonb language sql security definer stable set search_path=public as $$select jsonb_build_object('tables',(select coalesce(jsonb_agg(tablename order by tablename),'[]')from pg_tables where schemaname='public'),'columns',(select coalesce(jsonb_object_agg(table_name,cols),'{}')from(select table_name,jsonb_agg(column_name order by ordinal_position)cols from information_schema.columns where table_schema='public'group by table_name)x),'functions',(select coalesce(jsonb_agg(proname order by proname),'[]')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),'indexes',(select coalesce(jsonb_agg(indexname order by indexname),'[]')from pg_indexes where schemaname='public'),'buckets',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'public',public)order by id),'[]')from storage.buckets),'migrations',(select coalesce(jsonb_agg(jsonb_build_object('migration_number',migration_number,'migration_name',migration_name,'checksum',checksum,'applied_at',applied_at)order by migration_number),'[]')from app_schema_migrations))$$;
create or replace function record_schema_migration_if_objects_exist(p_number text,p_name text,p_checksum text,p_tables text[],p_functions text[],p_applied_by text,p_environment text,p_notes text default null)returns boolean language plpgsql security definer set search_path=public as $$declare x text;begin foreach x in array coalesce(p_tables,'{}')loop if to_regclass('public.'||x)is null then return false;end if;end loop;foreach x in array coalesce(p_functions,'{}')loop if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=x)then return false;end if;end loop;insert into app_schema_migrations(migration_number,migration_name,checksum,applied_by,environment,notes)values(p_number,p_name,p_checksum,p_applied_by,p_environment,p_notes)on conflict(migration_number)do update set migration_name=excluded.migration_name,checksum=excluded.checksum,notes=excluded.notes;return true;end$$;
do $$declare t text;begin foreach t in array array['app_schema_migrations','application_operational_errors','application_delivery_attempts','application_document_generation']loop execute format('alter table %I enable row level security',t);execute format('create policy "deployment diagnostics service role only" on %I for all using(auth.role()=''service_role'')with check(auth.role()=''service_role'')',t);end loop;end$$;
revoke all on function app_readiness_snapshot(),record_schema_migration_if_objects_exist(text,text,text,text[],text[],text,text,text)from public,anon,authenticated;grant execute on function app_readiness_snapshot(),record_schema_migration_if_objects_exist(text,text,text,text[],text[],text,text,text)to service_role;
insert into app_schema_migrations(migration_number,migration_name,checksum,applied_by,environment,notes)values('0028','deployment_readiness_and_migration_history','self-recorded-v1','migration','deployment','Readiness schema installed; earlier migrations are recorded only by verified bootstrap.')on conflict(migration_number)do nothing;
notify pgrst,'reload schema';
